<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Pointly POS | Users</title><?= view('partials/styles') ?></head>
<body><div class="app-shell"><?= view('partials/nav', ['active' => 'users']) ?><main class="content"><header class="topbar"><div><p class="eyebrow">Access management</p><h1>User accounts</h1><p class="subtitle">Review the staff members registered in your POS system.</p></div><div class="profile"><div class="avatar">AD</div> Admin account</div></header>
<section class="stat-grid"><div class="stat"><div class="stat-icon">♧</div><div><strong><?= count($users) ?></strong><span>Registered users</span></div></div><div class="stat"><div class="stat-icon">◈</div><div><strong>04</strong><span>Access roles</span></div></div><div class="stat"><div class="stat-icon">✓</div><div><strong>100%</strong><span>Account status</span></div></div></section>
<section class="panel"><div class="panel-heading"><h2>Staff directory</h2><span><?= count($users) ?> records found</span></div><div class="table-wrap"><table><thead><tr><th>User</th><th>Full name</th><th>Role</th><th>Status</th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td><div class="person"><span class="person-avatar"><?= esc(strtoupper(substr($user['username'], 0, 1))) ?></span><?= esc($user['username']) ?></div></td><td><?= esc($user['full_name']) ?></td><td><span class="badge <?= strtolower($user['role']) === 'manager' ? 'manager' : (strtolower($user['role']) === 'administrator' ? 'admin' : '') ?>"><?= esc($user['role']) ?></span></td><td><span class="badge">Active</span></td></tr><?php endforeach; ?></tbody></table></div></section>
</main></div></body></html>
